"""Splits returned OSM elements into list of ways and list of nodes

	Args:
		osmElements: list of nodes and ways returned from OSM query

	Returns:
		tuple containing (list of ways, list of nodes)
	"""
def splitElements(osmElements: Any) -> object {
    nodes = [];
    ways = [];
    garbage = [];
    for element in osmElements {
        if (element['type'] == 'node') {
            nodes.append(element);
        } elif (element['type'] == 'way') {
            ways.append(element);
        } else {
            garbage.append(element);
        }
    }
    return (ways, nodes);
}

"""Returns i + the ordinal indicator for the number.

    Example: ordinal(3) => '3rd'
    """
def ordinal(i: Any) -> object {
    i = int(i);
    if ((i % 100) in (11, 12, 13)) {
        return ('%sth' % i);
    }
    ord = 'th';
    `test = i % 10;
    if (`test == 1) {
        ord = 'st';
    } elif (`test == 2) {
        ord = 'nd';
    } elif (`test == 3) {
        ord = 'rd';
    }
    return ('%s%s' % (i, ord));
}

